"""Independent tests for reduce.py: Dominating Set -> SAT.

We implement our own solvers from the problem definitions and compare the
answer of the source instance with the answer of its reduction.
"""
from __future__ import annotations

import itertools
import random

from problems import DominatingSet, Sat
from reduce import reduce


# ----------------------------------------------------------------------
# Brute-force solver for Dominating Set (exhaustive over subsets <= k).
def brute_dominating(inst):
    n = inst["n"]
    edges = inst["edges"]
    k = inst["k"]
    if k < 0:
        return False
    if n == 0:
        return True
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for size in range(0, min(k, n) + 1):
        for comb in itertools.combinations(range(n), size):
            D = set(comb)
            if all(v in D or (adj[v] & D) for v in range(n)):
                return True
    return False


# ----------------------------------------------------------------------
# Brute-force solver for SAT: enumerate all assignments (small m only).
def brute_sat_enum(inst):
    m = inst["num_vars"]
    clauses = inst["clauses"]
    for bits in itertools.product((False, True), repeat=m):
        ok = True
        for clause in clauses:
            if not any((lit > 0) == bits[abs(lit) - 1] for lit in clause):
                ok = False
                break
        if ok:
            return True
    return False


# ----------------------------------------------------------------------
# Exact DPLL solver (used for larger instances); cross-checked below.
def dpll_sat(inst):
    m = inst["num_vars"]
    clauses = [list(c) for c in inst["clauses"]]

    def simplify(clauses, var, val):
        out = []
        for c in clauses:
            if (var if val else -var) in c:
                continue
            nc = [l for l in c if l != (-var if val else var)]
            out.append(nc)
        return out

    def dpll(clauses):
        while True:
            unit = None
            for c in clauses:
                if len(c) == 0:
                    return False
                if len(c) == 1:
                    unit = c[0]
                    break
            if unit is None:
                break
            clauses = simplify(clauses, abs(unit), unit > 0)
        vars_left = {abs(l) for c in clauses for l in c}
        if not vars_left:
            return True
        v = min(vars_left)
        for val in (True, False):
            if dpll(simplify(clauses, v, val)):
                return True
        return False

    return dpll(clauses)


def all_graphs(n):
    possible = list(itertools.combinations(range(n), 2))
    for mask in range(1 << len(possible)):
        edges = [list(e) for i, e in enumerate(possible) if mask >> i & 1]
        yield edges


def main():
    tests_run = 0
    tests_passed = 0
    failures = []

    def check(src, tag):
        nonlocal tests_run, tests_passed
        tests_run += 1
        DominatingSet.validate(src)
        tgt = reduce(src)
        Sat.validate(tgt)
        want = brute_dominating(src)
        got = dpll_sat(tgt)
        if want == got:
            tests_passed += 1
        else:
            failures.append((tag, src, tgt, want, got))

    # Cross-check DPLL against enumeration on random small formulas.
    rng = random.Random(12345)
    for _ in range(3000):
        m = rng.randint(0, 6)
        nclauses = rng.randint(0, 6)
        clauses = []
        for _ in range(nclauses):
            length = rng.randint(0, 3)
            clauses.append([rng.choice([-1, 1]) * rng.randint(1, m) for _ in range(length)] if m > 0 else [])
        inst = {"num_vars": m, "clauses": clauses}
        a = brute_sat_enum(inst)
        b = dpll_sat(inst)
        tests_run += 1
        if a == b:
            tests_passed += 1
        else:
            failures.append(("dpll-crosscheck", inst, None, a, b))

    # Exhaustive small graphs, all k in a range covering edge cases.
    for n in range(0, 5):
        for edges in all_graphs(n):
            for k in range(-2, n + 3):
                src = {"n": n, "edges": edges, "k": k}
                check(src, f"exhaustive n={n} k={k}")

    # Random slightly larger graphs.
    for _ in range(1500):
        n = rng.randint(0, 6)
        possible = list(itertools.combinations(range(n), 2))
        edges = [list(e) for e in possible if rng.random() < 0.5]
        k = rng.randint(-2, n + 2)
        src = {"n": n, "edges": edges, "k": k}
        check(src, f"random n={n} k={k}")

    # Random larger graphs with k in the Sinz range.
    for _ in range(400):
        n = rng.randint(4, 8)
        possible = list(itertools.combinations(range(n), 2))
        edges = [list(e) for e in possible if rng.random() < 0.4]
        k = rng.randint(0, n - 1)
        src = {"n": n, "edges": edges, "k": k}
        check(src, f"random-large n={n} k={k}")

    print(f"tests_run={tests_run} tests_passed={tests_passed} failures={len(failures)}")
    for f in failures[:10]:
        print("FAIL:", f)

    return tests_run, tests_passed, failures


if __name__ == "__main__":
    main()
