        out = []
        for c in clauses:
            if (var if val else -var) in c:
                continue
            out.append([l for l in c if l != (-var if val else var)])
        return out

    def dpll(clauses):
        while True:
            unit = None
            for c in clauses:
                if len(c) == 0:
                    return False
                if len(c) == 1:
                    unit = c[0]
                    break
            if unit is None:
